"""Encouraging faith-and-practice lesson with source-labelled research."""
import copy,re
SOURCES=[
 {'title':'Matthew 17:20 and Luke 17:6 · faith and the mustard seed','url':'https://www.biblegateway.com/passage/?search=Matthew+17%3A20%2CLuke+17%3A6&version=KJV','kind':'Scripture','summary':'Jesus uses a tiny seed to teach the significance of faith in the face of seemingly immense obstacles. Read each saying within its surrounding passage.'},
 {'title':'Matthew 13:31–32 · growth and shelter','url':'https://www.biblegateway.com/passage/?search=Matthew+13%3A31-32&version=KJV','kind':'Scripture','summary':'The kingdom is compared with a mustard seed that grows into a plant with branches where birds find a place. This is a different passage from the mountain-moving saying.'},
 {'title':'Bandura, Adams and Beyer (1977) · self-efficacy experiment','url':'https://pubmed.ncbi.nlm.nih.gov/15093/','kind':'Original research','summary':'In this experiment, mastery experiences strengthened efficacy expectations and approach behaviour. Practical lesson: build confidence through achievable experiences and feedback. The study examined particular tasks and participants.'},
 {'title':'Yeager and colleagues (2019) · national learning-mindset experiment','url':'https://www.nature.com/articles/s41586-019-1466-y','kind':'Original randomised study','summary':'A short intervention supported grades among lower-achieving pupils and advanced-maths enrolment overall. A supportive learning environment mattered. Pair an encouraging belief with good strategies and opportunities.'},
 {'title':'Expectation effects in working memory training (2022)','url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC9477404/','kind':'Original research','summary':'The study examined how expectations contribute to measured cognitive-training outcomes. Use expectations as one part of a learning design, alongside practice and comparison conditions. Full-text retrieval was blocked during preparation; the indexed abstract and bibliographic record were available.'},
 {'title':'Mechanisms of implementation intentions (2008)','url':'https://pubmed.ncbi.nlm.nih.gov/18096108/','kind':'Research synthesis','summary':'If-then planning connects an intended action with a recognisable cue. Translate a broad aspiration into a specific next action and check whether it occurred.'},
 {'title':'Self-talk and sports performance · research synthesis','url':'https://pubmed.ncbi.nlm.nih.gov/26167788/','kind':'Research synthesis','summary':'Research supports task-focused self-talk as a useful performance strategy in studied sporting contexts. Practise concise instructions and encouragement matched to the task.'},
 {'title':'Growth-mindset intervention evidence review (2023)','url':'https://pubmed.ncbi.nlm.nih.gov/36326645/','kind':'Research synthesis','summary':'Study quality, context and the particular outcome affect conclusions about mindset interventions. Build encouragement around effective instruction, resources, practice and feedback, and evaluate the result.'}]
CHAPTERS=[
 {'title':'The seed is enough to begin','text':'A seed is small and vulnerable, yet its smallness is not a verdict against its future. Begin with the faith and resources you have. Let the first act be small enough to do and meaningful enough to nourish.'},
 {'title':'Two mustard-seed teachings','text':'Matthew 17:20 and Luke 17:6 address faith facing immense obstacles. Matthew 13:31–32 describes growth and shelter. Together they invite a Christian reflection on beginnings, trust, perseverance and generosity. The botanical picture supports the teaching rather than measuring anyone’s faith.'},
 {'title':'From a closed sentence to an opening','text':'Replace an identity sentence such as “I am incapable” with a task-specific question: What can I learn, practise, ask for or arrange next? An obstacle becomes information for the path.'},
 {'title':'Roots: small experiences of mastery','text':'Choose a reachable step, attempt it, observe the result and adjust. Confidence and skill can support each other. Encouragement is strongest when the learner has patient teaching, time and resources.'},
 {'title':'A cue becomes an action','text':'Make an if-then plan: when a recognisable moment arrives, take one specific step. Decide in advance what completion looks like. If the attempt reveals a missing resource, make that resource the next task.'},
 {'title':'The surrounding soil','text':'The seed grows within conditions. People need opportunity, rest, instruction, belonging and material support. Help the learner and improve the environment together; setbacks need not become blame.'},
 {'title':'Flowering becomes shelter','text':'The mature image is generous: branches hold birds. Let growing capability become provision, patient companionship, useful work and protection of vulnerable beings. This joins the app’s souls-over-digits orientation.'},
 {'title':'How the app should speak','text':'Acknowledge the purpose, identify what is already possible, explain the missing prerequisite and offer a useful next step. Report real progress clearly. Faith, research findings and verified software capabilities each retain their own meaningful place.'}]
def lesson():return {'title':'The mustard seed · from small faith to generous shelter','image':'/assets/mustard-seed-growth.png','quote':'Small enough to hold; alive enough to grow.','chapters':copy.deepcopy(CHAPTERS),'sources':copy.deepcopy(SOURCES),'practice_path':['Name the goal','Choose a small step','Identify a cue','Make an if-then plan','Attempt','Observe and learn','Grow toward service'],'research_scope':'A curated starting library spanning self-efficacy, mindset, expectation, self-talk and planning—not every study. Scientific summaries concern the tasks studied; the scripture supplies the spiritual reflection.','app_assessment':{'already_present':['Native task planning','Verified small skills','Remembered outcomes','Source-labelled research'],'next_improvement':['Replace blanket inability language with a concrete capability and next-step explanation','Test transfer to new tasks','Improve resources and instruction alongside encouragement'],'principle':'Encourage agency without blaming learners for setbacks or inventing completed capabilities.'}}
def plan(body):
 if not isinstance(body,dict):raise ValueError('Provide a goal and practice plan')
 fields={}
 for key in ('goal','cue','step','completion'):
  value=body.get(key,'')
  if not isinstance(value,str) or not value.strip() or len(value)>1000:raise ValueError('Complete '+key+' in 1–1000 characters')
  if re.search(r'(?i)(password|api.?key|token)\s*[:=]|sk-[A-Za-z0-9_-]{10,}',value):raise ValueError('Keep credentials out of lesson practice')
  fields[key]=value.strip()
 return {**fields,'if_then':'When '+fields['cue']+', I will '+fields['step']+'.','encouragement':'Begin with this reachable step. Learn from what happens and ask for the support that helps you grow.','verification':'Check: '+fields['completion'],'next_if_blocked':'Identify the missing resource, support or prerequisite and make a new small plan.','execution':False,'scope':'An original practice plan; no command is executed or outcome guaranteed.'}
